function parameter(name,type='int') { return {name,type,description:words[name] || `${name}の値`}; }
function signature(language,name,parameters) {
 const list=parameters.map(p=>language==='rust'?`mut ${p.name}: i32`:language==='go'?`${p.name} ${p.type==='string'?'string':'int'}`:['python','lua'].includes(language)?p.name:`${p.type==='string'?'String':'int'} ${p.name}`).join(', ');
 if(language==='python')return `def ${name}(${list}):`;
 if(language==='lua')return `function ${name}(${list})`;
 if(language==='rust')return `fn ${name}(${list}) -> i32 {`;
 if(language==='go')return `func ${name}(${list}) int {`;
 return `${['java','csharp'].includes(language)?'static ':''}int ${name}(${list}) {`;
}
function wrapFunction(language,name,parameters,body,headers=[]) {
 const includes=language==='cpp'?headers.map(h=>`#include <${h}>\n`).join(''):'';
 return includes+signature(language,name,parameters)+'\n'+body.split('\n').map(l=>'    '+l).join('\n')+(language==='python'?'':language==='lua'?'\nend':'\n}');
}
function literal(value) { return typeof value==='string'?JSON.stringify(value):String(value); }
function functionHarness(quiz,source) {
 const calls=quiz.cases.map(c=>`${quiz.functionName}(${c.args.map(literal).join(', ')})`);
 let program;
 switch(quiz.language) {
  case 'cpp':program='#include <iostream>\n'+source+'\nint main() {\n'+calls.map(c=>`std::cout << ${c} << "\\n";`).join('\n')+'\n}\n';break;
  case 'csharp':program='class Program {\n'+source+'\nstatic void Main(string[] args) {\n'+calls.map(c=>`System.Console.WriteLine(${c});`).join('\n')+'\n}\n}\n';break;
  case 'java':program='public class Main {\n'+source+'\npublic static void main(String[] args) {\n'+calls.map(c=>`System.out.println(${c});`).join('\n')+'\n}\n}\n';break;
  case 'rust':program=source+'\nfn main() {\n'+calls.map(c=>`println!("{}", ${c});`).join('\n')+'\n}\n';break;
  case 'go':program='package main\nimport "fmt"\n'+source+'\nfunc main() {\n'+calls.map(c=>`fmt.Println(${c})`).join('\n')+'\n}\n';break;
  case 'python':program=source+'\n'+calls.map(c=>`print(${c})`).join('\n')+'\n';break;
  case 'lua':program=source+'\n'+calls.map(c=>`print(${c})`).join('\n')+'\n';break;
  default:throw new RangeError('Unsupported quiz language');
 }
 return {language:quiz.language,source:program,expected:quiz.cases.map(c=>c.expected),caseIds:quiz.cases.map(c=>c.id),fileName:quiz.language==='java'?'Main.java':undefined};
}
function finish(metadata,parameters,source,cases,description) {
 const {language,subject,index,topicId}=metadata, name=functionName(language,topicId);
 const marker=language==='python'?'#':language==='lua'?'--':'//';
 const starter=wrapFunction(language,name,parameters,`${marker} Implement the behavior described in the exercise.\nreturn 0${['cpp','csharp','java','rust'].includes(language)?';':''}`);
 const quiz={...metadata,id:`quiz/v${QUIZ_VERSION}/${language}/${subject}/${topicId}`,lessonBaseId:`${language}/${subject}/${topicId}`,version:QUIZ_VERSION,functionName:name,parameters,description,referenceSource:source,starterSource:starter,cases:cases.map((c,i)=>({id:`case-${String(i+1).padStart(2,'0')}`,...c,expected:c.expected===0?0:c.expected})),supported:true,limitations:[]};
 quiz.createHarness=submitted=>functionHarness(quiz,submitted);
 return quiz;
}
