function specificQuiz(language,subject,index,topic) {
 const def=specific[topic.id];
 if(!def)throw new Error(`Missing quiz definition: ${topic.id}`);
 const marker=language==='python'?'#':language==='lua'?'--':'//';
 const comments=topic.comments.map(c=>`${marker} ${c.en}`).join('\n');
 const cases=def.examples.map(args=>({args:[...args],expected:def.oracle(...args)}));
 // A second set changes an actual data input, never the flag/domain selector.
 // This also covers captures and state lifetimes with independent invocations.
 const variable=def.parameters.findIndex(p=>p.type==='int'&&!['missing','failed','idle'].includes(p.name));
 for(const args of def.examples) {
  const changed=[...args];changed[variable]+=2;
  cases.push({args:changed,expected:def.oracle(...changed)});
 }
 const description=`${def.description} 引数は明記した文字列、0/1の選択値、または32bit整数。計算結果が32bit範囲を超える入力は出題しない。毎ケース新しく状態を作り、前の呼出しの状態を残さない。`;
 return finish({language,subject,index,topicId:topic.id,title:topic.title},def.parameters,wrapFunction(language,functionName(language,topic.id),def.parameters,comments+'\n'+def.body,def.headers),cases,description);
}

