function fixtureSql(rows,counterLimit) {
 return `DROP TABLE IF EXISTS sample;\nDROP TABLE IF EXISTS quiz_config;\nCREATE TABLE sample(id INTEGER PRIMARY KEY, amount INTEGER NOT NULL, group_id INTEGER NOT NULL, enabled INTEGER NOT NULL);\nCREATE TABLE quiz_config(counter_limit INTEGER NOT NULL);\nINSERT INTO quiz_config VALUES (${counterLimit});\nINSERT INTO sample VALUES ${rows.map(row=>'('+row.join(', ')+')').join(', ')};\n`;
}
function sqlQuiz(subject,index,topic) {
 const query=topic.id==='recursive_counter'?topic.query.replace('n < 5','n < (SELECT counter_limit FROM quiz_config)'):topic.query;
 const cases=SQL_CASES[topic.id].map((c,i)=>({id:`case-${String(i+1).padStart(2,'0')}`,args:[],fixtureRows:c.rows.map(r=>[...r]),counterLimit:c.counterLimit,expected:c.expected}));
 const quiz={language:'sql',subject,index,topicId:topic.id,title:topic.title,id:`quiz/v${QUIZ_VERSION}/sql/${subject}/${topic.id}`,lessonBaseId:`sql/${subject}/${topic.id}`,version:QUIZ_VERSION,functionName:null,parameters:[{name:'sample',type:'table',description:'id:一意な正整数、amount:符号付き整数、group_id:1〜4、enabled:0または1。4〜6行。NULLなし。'},...(topic.id==='recursive_counter'?[parameter('counter_limit')]:[])],description:`${SQL_SPEC[topic.id]} sample(id, amount, group_id, enabled)を読むSELECTを一つ書き、1行1列の整数を返す。COUNTの空集合は0。SUM/AVG/MIN/MAXの空集合はSQLiteに従いNULLだが、採点fixtureは必要な集計が数値となるものを使う。整数CASTは0方向への切捨て。fixtureごとにDBを作り直し、sampleを変更しない。`,referenceSource:topic.comments.map(c=>'-- '+c.en).join('\n')+'\n'+query,starterSource:'-- Return one numeric result from the supplied sample table.\nSELECT 0;',cases,supported:true,limitations:[]};
 quiz.createHarness=source=>({language:'sql',source:cases.map(c=>fixtureSql(c.fixtureRows,c.counterLimit)+source+'\n').join('\n'),expected:cases.map(c=>c.expected),caseIds:cases.map(c=>c.id),executions:cases.map(c=>({source,fixtureSql:fixtureSql(c.fixtureRows,c.counterLimit),expected:c.expected}))});
 return quiz;
}
function position(language,subject,index) {
 if(!QUIZ_LANGUAGES.includes(language))throw new RangeError(`Unsupported quiz language: ${language}`);
 if(!QUIZ_SUBJECTS.includes(subject))throw new RangeError(`Unsupported quiz subject: ${subject}`);
 const number=Number.isFinite(index)?Math.max(0,Math.floor(index))%QUIZ_TOPICS_PER_SUBJECT:0;
 return number;
}
export function quizId(language,subject,index=0) {
 const number=position(language,subject,index);
 const topic=language==='sql'?SQL_TOPICS[subject][number]:number<14?TOPICS[subject][number]:IDIOMS[language][subject][number-14];
 return `quiz/v${QUIZ_VERSION}/${language}/${subject}/${topic.id}`;
}
export function quizAt(language,subject,index=0) {
 const number=position(language,subject,index), id=quizId(language,subject,number);
 if(!cache.has(id)) {
  const quiz=language==='sql'?sqlQuiz(subject,number,SQL_TOPICS[subject][number]):number<14?sharedQuiz(language,subject,number,TOPICS[subject][number]):specificQuiz(language,subject,number,IDIOMS[language][subject][number-14]);
  cache.set(id,quiz);
 }
 return cache.get(id);
}
export function quizCatalog() { return QUIZ_LANGUAGES.flatMap(language=>QUIZ_SUBJECTS.flatMap(subject=>Array.from({length:QUIZ_TOPICS_PER_SUBJECT},(_,index)=>quizAt(language,subject,index)))); }
export function quizById(id) {
 if(typeof id!=='string')return null;
 const parts=id.split('/');
 if(parts.length!==5||parts[0]!=='quiz'||parts[1]!==`v${QUIZ_VERSION}`||!QUIZ_LANGUAGES.includes(parts[2])||!QUIZ_SUBJECTS.includes(parts[3]))return null;
 for(let i=0;i<QUIZ_TOPICS_PER_SUBJECT;i++)if(quizId(parts[2],parts[3],i)===id)return quizAt(parts[2],parts[3],i);
 return null;
}
